<script setup>import{Head,useForm,router}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';defineProps({groups:Array});const f=useForm({name:'',description:'',color:'#10b981'});const add=()=>f.post(route('groups.store'),{onSuccess:()=>f.reset('name','description')});</script><template><Head title="Groups"/><AuthenticatedLayout><template #header><div><h1 class="text-lg font-semibold text-white">Monitoring groups</h1><p class="text-xs text-slate-500">Organize infrastructure by location or purpose</p></div></template><form v-if="$page.props.auth.user.role==='admin'" @submit.prevent="add" class="mb-5 flex flex-wrap gap-2"><input v-model="f.name" required placeholder="New group name" class="rounded-lg border-slate-700 bg-slate-900 text-sm"><input v-model="f.description" placeholder="Description" class="min-w-64 flex-1 rounded-lg border-slate-700 bg-slate-900 text-sm"><input v-model="f.color" type="color" class="h-10 rounded bg-slate-900"><button class="rounded-lg bg-emerald-500 px-4 text-sm font-bold text-slate-950">Create</button></form><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><div v-for="g in groups" class="rounded-xl border border-slate-800 bg-slate-900 p-5"><div class="flex justify-between"><h2 class="font-semibold text-white"><i :style="{background:g.color}" class="mr-2 inline-block h-2.5 w-2.5 rounded-full"></i>{{g.name}}</h2><button v-if="$page.props.auth.user.role==='admin'" @click="confirm('Delete group? Hosts become ungrouped.')&&router.delete(route('groups.destroy',g.id))" class="text-xs text-red-400">Delete</button></div><p class="mt-2 min-h-10 text-sm text-slate-500">{{g.description||'No description'}}</p><div class="mt-5 grid grid-cols-4 border-t border-slate-800 pt-4 text-center"><div><b>{{g.hosts_count}}</b><small>Total</small></div><div class="text-emerald-400"><b>{{g.active_count}}</b><small>Active</small></div><div class="text-red-400"><b>{{g.down_count}}</b><small>Down</small></div><div class="text-amber-400"><b>{{g.unstable_count}}</b><small>Unstable</small></div></div></div></div></AuthenticatedLayout></template>
